#!/usr/bin/env python
"""Printed-game-map style preview of the whole world -> docs/v2/shots/world-layout/map.png (regenerated by the tool)."""
import json, math, os, sys
import numpy as np
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from PIL import Image, ImageDraw, ImageFont, ImageFilter
from scipy import ndimage
from wl import real as R, land as LD
from wl.util import BOUNDS, NX, NZ, CELL, fbm
F = json.load(open(os.path.join(R.OUT, 'features.json')))
rd = R.load_real()
from wl.util import raster_polys
from shapely.geometry import Polygon as _PG, box as _bx
S = 6.0                                     # meters per pixel while drawing (downsampled 2x at the end)
Wp, Hp = int((BOUNDS['maxX'] - BOUNDS['minX']) / S), int((BOUNDS['maxZ'] - BOUNDS['minZ']) / S)
def px(p): return ((p[0] - BOUNDS['minX']) / S, (p[1] - BOUNDS['minZ']) / S)
# --- ocean: depth-like gradient from distance to land
_rr = F['realRect']
mask = raster_polys([_PG(l['outer'], l.get('holes') or []).buffer(0) for l in F['land']], (NZ, NX)) > 0
d = ndimage.distance_transform_edt(~mask).astype(np.float32) * CELL
n = fbm(mask.shape, 700, 'mapsea', octaves=4)
PAL = json.load(open(os.path.join(R.OUT, 'palette.json')))
sea = np.zeros(mask.shape + (3,), np.float32) + np.array(PAL['ocean'], np.float32) * (1.0 + 0.05 * n[..., None])
band = 0.0
img = Image.fromarray(np.clip(sea + band, 0, 255).astype(np.uint8)).resize((Wp, Hp), Image.BICUBIC)
dr = ImageDraw.Draw(img)
_sh = Image.new('L', img.size, 0); _sd = ImageDraw.Draw(_sh)
for q_ in F.get('shallows', []):
    _sd.polygon([px(p) for p in q_['outer']], fill=255)
    for h_ in q_.get('holes', []): _sd.polygon([px(p) for p in h_], fill=0)
_sh = _sh.filter(ImageFilter.GaussianBlur(4))
img.paste(tuple(min(255, int(v * 1.12)) for v in PAL['shallow']), (0, 0), _sh)
dr = ImageDraw.Draw(img)
def poly(d_, fill, outline=None):
    global img, dr
    if not d_.get('holes'):
        dr.polygon([px(p) for p in d_['outer']], fill=fill, outline=outline); return
    o = [px(p) for p in d_['outer']]
    x0, y0 = int(min(p[0] for p in o)) - 1, int(min(p[1] for p in o)) - 1
    x1, y1 = int(max(p[0] for p in o)) + 2, int(max(p[1] for p in o)) + 2
    m = Image.new('L', (x1 - x0, y1 - y0), 0); md = ImageDraw.Draw(m)
    md.polygon([(u - x0, v - y0) for u, v in o], fill=255)
    for h_ in d_['holes']: md.polygon([(px(p)[0] - x0, px(p)[1] - y0) for p in h_], fill=0)
    img.paste(fill, (x0, y0), m)
def shp(g, fill):
    for q in (g.geoms if hasattr(g, 'geoms') else [g]):
        if q.geom_type == 'Polygon' and not q.is_empty and len(q.exterior.coords) >= 3: dr.polygon([px(p) for p in q.exterior.coords], fill=fill)
LAND = tuple(PAL['land'])
for l in F['land']: poly(l, LAND)

# re-paint real land inside the rect in urban grey, with its holes as water
rr = F['realRect']
from shapely.geometry import box, Point as _Pt
from shapely.prepared import prep as _prep
from shapely.ops import unary_union as _uu2
_LANDP = _prep(_uu2([_PG(l['outer'], l.get('holes') or []).buffer(0) for l in F['land']]))
g = box(rr['minX'], rr['minZ'], rr['maxX'], rr['maxZ'])
COL0 = {'beach': (247, 234, 168), 'sand': (236, 226, 190), 'scrub': (196, 204, 140), 'mangrove': (92, 176, 120), 'wetland': (140, 206, 150), 'sawgrass': (150, 212, 150),
       'forest': (150, 204, 100), 'pine': (150, 204, 100), 'farmland': (226, 220, 140), 'grove': (164, 212, 104), 'grass': (176, 220, 120), 'park': (160, 214, 110),
       'parking': (206, 204, 198), 'paved': (198, 198, 194), 'apron': (214, 214, 212), 'golf': (120, 170, 90), 'runway': (132, 134, 138), 'taxiway': (168, 170, 172), 'campground': (188, 206, 150)}
_m = lambda c, k: tuple(int(c[i] * k) for i in range(3))
COL = dict(COL0, beach=tuple(PAL['sand']), sand=tuple(PAL['sand']), forest=tuple(PAL['forest']), pine=tuple(PAL['forest']), residential=tuple(PAL['urban']), sawgrass=_m(PAL['forest'], 1.12), grass=_m(PAL['land'], 1.05),
           grove=_m(PAL['land'], 0.92), farmland=(150, 150, 84), mangrove=_m(PAL['forest'], 0.9), wetland=_m(PAL['forest'], 1.1), park=_m(PAL['land'], 1.08), scrub=_m(PAL['land'], 0.95), campground=_m(PAL['land'], 1.0))
order = ['residential', 'golf', 'sawgrass', 'forest', 'farmland', 'grove', 'grass', 'scrub', 'wetland', 'mangrove', 'sand', 'beach', 'park', 'campground', 'parking', 'paved', 'apron', 'taxiway', 'runway']
for k in order:
    for a in F['areas']:
        if a['kind'] == k: poly(a, COL[k])
# marsh speckle
rs = np.random.default_rng(7)
for a in F['areas']:
    if a['kind'] == 'sawgrass':
        xs = [p[0] for p in a['outer']]; zs = [p[1] for p in a['outer']]
        from shapely.geometry import Polygon, Point
        P = Polygon(a['outer'])
        for _ in range(int(P.area / 2600)):
            x, z = rs.uniform(min(xs), max(xs)), rs.uniform(min(zs), max(zs))
            if P.contains(Point(x, z)):
                u, v = px((x, z)); w = rs.uniform(3, 9)
                dr.ellipse([u - w, v - w * 0.5, u + w, v + w * 0.5], fill=(128, 200, 214))
for w in F['water']: poly(w, tuple(PAL['water']))
# hillshade
h = F['heights']; H = np.fromfile(os.path.join(R.OUT, h['file']), '<i2').reshape(h['nz'], h['nx']).astype(np.float32) * h['unit']
gy, gx = np.gradient(H, h['cell'])
shade = np.clip(1.0 + 0.9 * (-gx - gy) / 1.4, 0.72, 1.14)
tint = np.clip(H / 260.0, 0, 1) ** 0.7
sh = Image.fromarray((np.clip(shade, 0, 2) * 100).astype(np.uint8)).resize((Wp, Hp), Image.BICUBIC)
arr = np.asarray(img).astype(np.float32) * (np.asarray(sh).astype(np.float32)[..., None] / 100.0)
tn = np.asarray(Image.fromarray((tint * 255).astype(np.uint8)).resize((Wp, Hp), Image.BICUBIC)).astype(np.float32)[..., None] / 255.0
arr = arr * (1 - 0.35 * tn) + np.array(PAL['forest'], np.float32) * 0.8 * 0.35 * tn
_tex = np.asarray(Image.fromarray(((fbm(mask.shape, 60, 'tex', octaves=3) * 0.5 + 0.5) * 255).astype(np.uint8)).resize((Wp, Hp), Image.BILINEAR)).astype(np.float32)[..., None] / 255.0
_lm = np.asarray(Image.fromarray((mask * 255).astype(np.uint8)).resize((Wp, Hp), Image.BILINEAR)).astype(np.float32)[..., None] / 255.0
arr = arr * (1.0 - 0.10 * _lm + 0.20 * _lm * _tex)
img = Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8)); dr = ImageDraw.Draw(img)
# buildings
for c, hh in rd.get('buildings', []):
    if rr['minX'] < c[0][0] < rr['maxX'] and rr['minZ'] < c[0][1] < rr['maxZ'] and _LANDP.contains(_Pt(c[0])): dr.polygon([px(p) for p in c], fill=(236, 236, 232))
for b in F['buildings']: dr.polygon([px(p) for p in b['ring']], fill=(250, 250, 247) if b['zone'] != 'airport' else (238, 238, 240), outline=(170, 170, 166))
for p in F['paths']: dr.line([px(q) for q in p['pts']], fill=(150, 120, 90) if p['kind'] in ('dock', 'pier', 'boardwalk') else (168, 138, 96), width=max(1, int(p['width'] / S)))
# roads: casing then fill, minor first
ST = {'track': (1.4, (190, 180, 140), None), 'service': (1.2, (214, 208, 180), None), 'residential': (2.0, (226, 222, 204), None), 'tertiary': (2.8, (232, 226, 198), None),
      'secondary': (3.4, (236, 228, 190), (120, 124, 96)), 'primary': (4.0, (240, 230, 184), (116, 118, 90)), 'trunk': (4.6, (242, 232, 180), (110, 112, 86)),
      'motorway_link': (2.4, (240, 228, 172), (110, 112, 86)), 'motorway': (4.4, (244, 232, 170), (104, 104, 80))}
RK = list(ST.keys())
real_roads = [dict(pts=r['pts'], kind={'unclassified': 'residential', 'living_street': 'residential'}.get(r['kind'], r['kind']).replace('trunk_link', 'trunk').replace('primary_link', 'primary').replace('secondary_link', 'secondary').replace('tertiary_link', 'tertiary'), bridge=r['bridge'])
              for r in rd['roads'] if all(rr['minX'] - 5 < p[0] < rr['maxX'] + 5 and rr['minZ'] - 5 < p[1] < rr['maxZ'] + 5 for p in (r['pts'][0], r['pts'][-1])) and _LANDP.contains(_Pt(r['pts'][len(r['pts']) // 2]))]
allr = real_roads + F['roads']
for phase in (0, 1):
    for k in RK:
        w, fill, case = ST[k]
        for r in allr:
            if r['kind'] != k: continue
            pts = [px(p) for p in r['pts']]
            if phase == 0 and case: dr.line(pts, fill=case, width=int(round(w / S * 2.1 + 1.6)), joint='curve')
            if phase == 1: dr.line(pts, fill=fill, width=max(1, int(round(w / S * 2.1))), joint='curve')
img = img.resize((Wp // 2, Hp // 2), Image.LANCZOS); dr = ImageDraw.Draw(img); S2 = S * 2
def p2(p): return ((p[0] - BOUNDS['minX']) / S2, (p[1] - BOUNDS['minZ']) / S2)
def font(sz, bold=True):
    for f in ('/System/Library/Fonts/Avenir Next Condensed.ttc', '/System/Library/Fonts/Avenir Next.ttc', '/System/Library/Fonts/HelveticaNeue.ttc', '/System/Library/Fonts/Helvetica.ttc'):
        try: return ImageFont.truetype(f, sz, index=1 if bold else 0)
        except Exception: pass
    return ImageFont.load_default()
def label(x, z, text, sz, fill=(255, 255, 255), halo=(40, 70, 90)):
    f = font(sz); u, v = p2((x, z)); tw = dr.textlength(text, font=f)
    dr.text((u - tw / 2, v - sz / 2), text, font=f, fill=fill, stroke_width=2, stroke_fill=halo)
SZ = {'region': 21, 'airport': 20, 'key': 19, 'island': 19, 'town': 19, 'district': 17, 'park': 22, 'lake': 18, 'beach': 17}
for pl in F['places']:
    if pl['name'] in ('Pelican Point',): continue
    label(pl['x'], pl['z'], pl['name'].upper(), SZ.get(pl['kind'], 22), halo=(30, 80, 120) if pl['kind'] in ('lake',) else (50, 70, 60))
label(400, 300, 'MIAMI', 30); label(3650, 600, 'MIAMI BEACH', 15); label(4300, -9000, 'ATLANTIC OCEAN', 20, fill=(220, 240, 250), halo=(30, 70, 130))
label(-22000, -3000, 'GULF', 20, fill=(220, 240, 250), halo=(30, 70, 130))
for sp in F['setpieces']:
    if sp['id'] == 'nico_house':
        u, v = p2((sp['x'], sp['z'])); dr.ellipse([u - 15, v - 15, u + 15, v + 15], fill=(255, 255, 255), outline=(20, 20, 20), width=5)
        f = font(22); dr.text((u + 22, v - 12), "NICO'S HOUSE", font=f, fill=(255, 255, 255), stroke_width=3, stroke_fill=(20, 20, 20))
# scale bar, title, compass
x0, y0 = img.size[0] - 620, img.size[1] - 110
for i in range(4):
    dr.rectangle([x0 + i * 2000 / S2, y0, x0 + (i + 1) * 2000 / S2, y0 + 12], fill=(255, 255, 255) if i % 2 == 0 else (30, 50, 90), outline=(255, 255, 255))
f = font(20)
for i, t_ in enumerate(('0', '2 km', '4 km', '6 km', '8 km')): dr.text((x0 + i * 2000 / S2 - 10, y0 + 18), t_, font=f, fill=(255, 255, 255))
dr.text((60, 50), 'PORT SOLANA', font=font(56), fill=(255, 255, 255), stroke_width=4, stroke_fill=(30, 70, 130))
dr.text((64, 118), 'and the Keys  ·  world layout preview (tools/world)', font=font(26, False), fill=(235, 245, 250))
cx, cy = img.size[0] - 150, 160
dr.polygon([(cx, cy - 70), (cx - 18, cy), (cx + 18, cy)], fill=(255, 255, 255)); dr.polygon([(cx, cy + 70), (cx - 18, cy), (cx + 18, cy)], fill=(30, 50, 90), outline=(255, 255, 255))
dr.text((cx - 9, cy - 108), 'N', font=font(30), fill=(255, 255, 255))
dr.text((60, img.size[1] - 50), 'Real Miami: © OpenStreetMap contributors (ODbL)', font=font(18, False), fill=(225, 238, 246))
SFX = '_p7' if os.environ.get('WL_OUT') else ''
out = R.OUT if SFX else os.path.join(R.ROOT, 'docs', 'v2', 'shots', 'world-layout'); os.makedirs(out, exist_ok=True)
img.save(os.path.join(out, 'map.png'), optimize=True)
IH = int(F.get('imageTransform', {}).get('size', [1041, 1511])[1])
sm = img.resize((1041, IH), Image.LANCZOS)
ref = os.path.join(R.ROOT, 'references', 'ref_40_map_user_official.webp')
if os.path.exists(ref):
    rf = Image.open(ref).convert('RGB').resize((1041, IH)); o = Image.new('RGB', (2102, IH), (20, 20, 20)); o.paste(sm, (0, 0)); o.paste(rf, (1061, 0))
    os.makedirs(os.path.join(R.ROOT, 'docs', 'v2', 'compare'), exist_ok=True); o.save(os.path.join(R.ROOT, 'docs', 'v2', 'compare', f'world-layout_vs_ref40{SFX}.png'))
    o.resize((1401, 1000), Image.LANCZOS).save(os.path.join(R.ROOT, 'docs', 'v2', 'compare', f'world-layout_vs_ref40_small{SFX}.png'))
    k_ = img.size[0] / 1041.0; rfull = Image.open(ref).convert('RGB'); tiles = []
    for nm_, (x0_, y0_, x1_, y1_) in (('city_bay', (630, 560, 1000, 1010)), ('tern_key', (150, 1230, 400, 1440)), ('airport', (400, 780, 700, 990))):
        a_ = img.crop((int(x0_ * k_), int(y0_ * k_), int(x1_ * k_), int(y1_ * k_))); b_ = rfull.crop((x0_, y0_, x1_, y1_)).resize(a_.size, Image.LANCZOS)
        o_ = Image.new('RGB', (a_.size[0] * 2 + 16, a_.size[1]), (20, 20, 20)); o_.paste(a_, (0, 0)); o_.paste(b_, (a_.size[0] + 16, 0))
        o_.save(os.path.join(R.ROOT, 'docs', 'v2', 'compare', f'world-layout_crop_{nm_}{SFX}.png')); tiles.append(o_.resize((700, int(700 * o_.size[1] / o_.size[0])), Image.LANCZOS))
    sheet = Image.new('RGB', (700, sum(t.size[1] for t in tiles) + 16), (20, 20, 20)); yy = 0
    for t in tiles: sheet.paste(t, (0, yy)); yy += t.size[1] + 8
    sheet.save(os.path.join(R.ROOT, 'docs', 'v2', 'compare', f'world-layout_crops_small{SFX}.png'))
print('map', img.size)
